let _registered = false;

/**
 * Register DejaVu Sans (subset) with a jsPDF document instance. Idempotent:
 * safe to call before every render. The font is added to jsPDF's virtual
 * file system with a stable name; callers activate it via
 *   doc.setFont("DejaVuSans", "normal")
 * and switch back to Helvetica with doc.setFont("helvetica", ...) for
 * everything else so the PDF stays small.
 */
export function registerDejaVuSans(doc: any): void {
  // jsPDF's addFileToVFS/addFont keep font state on the doc instance, so we
  // must (re-)register per document. The _registered guard just skips work
  // when the same module is reused across doc instances that already have
  // it installed (jsPDF is a no-op on duplicate addFont with the same name).
  try {
    doc.addFileToVFS("DejaVuSans.ttf", DEJAVU_SANS_BASE64);
    doc.addFont("DejaVuSans.ttf", "DejaVuSans", "normal");
    _registered = true;
  } catch (err) {
    // Font registration failing shouldn't break the whole PDF — the caller
    // will just fall back to Helvetica and the ASCII replacements handle it.
    // eslint-disable-next-line no-console
    console.warn("[DryReport] DejaVu Sans registration failed:", err);
  }
}

export { _registered as dejavuSansRegistered };
